<?php
$runtime=json_decode(file_get_contents(dirname(__DIR__).'/.e2e/lifecycle/runtime.json'),TRUE);if(!preg_match('/^gulhouse_test_[a-zA-Z0-9_]+$/D',$runtime['schema']??''))throw new RuntimeException('Synthetic only');putenv('GULHOUSE_DATABASE='.$runtime['schema']);putenv('GULHOUSE_TEST_URL='.$runtime['url']);require __DIR__.'/http-helpers.php';
