list($s,$html)=request('/master/index.php/lifecycle/detail/'.$id);preg_match('/name="(csrf_[^"]+)" value="([a-f0-9]+)"/',$html,$token);$p[$token[1]]=$token[2];$f=tempnam(sys_get_temp_dir(),'ciko_scan_').'.pdf';$bytes=file_get_contents($root.'/tests/fixtures/payment-proof-valid.pdf')."\n%CIKO-".bin2hex(random_bytes(8));file_put_contents($f,$bytes);$p['scan_file']=new CURLFile($f,'application/pdf','CIKO-draft.pdf');$h=curl_init($base.'/master/index.php/lifecycle/action/'.$id);curl_setopt_array($h,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_FOLLOWLOCATION=>TRUE,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>$p));$html=curl_exec($h);curl_close($h);unlink($f);$draft=row('SELECT * FROM gh_facility_inspections WHERE case_id='.$id.' AND revision_of='.(int)$old['id'].' ORDER BY id DESC LIMIT 1');check($draft&&$draft['status']==='draft','incomplete correction allowed only as draft');
$tickets=count_rows('SELECT COUNT(*) n FROM gh_maintenance_tickets WHERE tenant_id='.(int)$c['tenant_id']);ci_action($id,'maintenance',array('inspection_id'=>$draft['id'],'item_id'=>$first,'issue_title'=>'CIKO forbidden draft ticket'));check(count_rows('SELECT COUNT(*) n FROM gh_maintenance_tickets WHERE tenant_id='.(int)$c['tenant_id'])===$tickets,'draft cannot create maintenance ticket through direct POST');
ci_action($id,'inspection_finalize',array('inspection_id'=>$draft['id'],'resident_signed'=>1,'manager_signed'=>1,'supervisor_signed'=>1));check(row('SELECT status FROM gh_facility_inspections WHERE id='.(int)$draft['id'])['status']==='draft','NULL actual quantity cannot become final despite signatures');
if($foreign){$before=count_rows('SELECT COUNT(*) n FROM gh_facility_inspections WHERE case_id='.$id);ci_action($id,'inspection_save',array('stage'=>$foreign['stage'],'revision_of'=>$foreign['id'],'check_date'=>date('Y-m-d'),'period'=>date('Y-m'),'officer_name'=>'CIKO','notes'=>'Attempt cross-case revision'));check(count_rows('SELECT COUNT(*) n FROM gh_facility_inspections WHERE case_id='.$id)===$before,'revision cannot reference another case');}
$originalRows=$db->query('SELECT * FROM gh_facility_inspection_rows WHERE inspection_id='.(int)$old['id'])->fetch_all(MYSQLI_ASSOC);ci_action($id,'inspection_save',array('inspection_id'=>$old['id'],'stage'=>'routine','check_date'=>date('Y-m-d'),'period'=>date('Y-m'),'officer_name'=>'CIKO overwrite','notes'=>'Forbidden overwrite'));check($db->query('SELECT * FROM gh_facility_inspection_rows WHERE inspection_id='.(int)$old['id'])->fetch_all(MYSQLI_ASSOC)===$originalRows,'final rows unchanged by direct overwrite');
ci_action($id,'verify_payment');check(row('SELECT status FROM gh_resident_cases WHERE id='.$id)['status']==='checked_out','reverify payment cannot reopen completed case');
$refunds=count_rows('SELECT COUNT(*) n FROM gh_refund_payments WHERE case_id='.$id);ci_action($id,'refund',array('amount'=>'999999999','transfer_date'=>date('Y-m-d'),'reference_no'=>'CIKO-over-refund'));check(count_rows('SELECT COUNT(*) n FROM gh_refund_payments WHERE case_id='.$id)===$refunds,'over-refund rejected');
