$ledger=count_rows('SELECT COUNT(*) n FROM gh_deposit_transactions WHERE stay_id='.(int)$c['stay_id']);post('/master/index.php/ops/deposits/save',array('tenant_id'=>$c['tenant_id'],'stay_id'=>$c['stay_id'],'room_id'=>$c['room_id'],'transaction_date'=>date('Y-m-d'),'transaction_type'=>'refund','amount'=>'1','method'=>'Synthetic','refund_inspection_confirmed'=>1,'refund_reason'=>'CIKO bypass'),'/master/index.php/deposits');check(count_rows('SELECT COUNT(*) n FROM gh_deposit_transactions WHERE stay_id='.(int)$c['stay_id'])===$ledger,'legacy deposit route cannot bypass managed refund proof');
